@page "/dashboard"
@rendermode InteractiveServer
@using sv_aeb99365f1d1479290fa757a263c85d3.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge bg-warning text-dark fs-6">@_alertCount</span>
        </p>
        <p class="text-muted small mb-0">Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</p>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdate = DateTime.Now;
    private CancellationTokenSource _cts = new();
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await PollAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(() =>
        {
            _alertCount = AlertService.LastKnownCount;
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        await PollAsync();
        _ = PollingLoopAsync(_cts.Token);
    }

    private async Task PollingLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await InvokeAsync(async () =>
                {
                    await PollAsync();
                    StateHasChanged();
                });
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task PollAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _alertCount = count;
        _lastUpdate = DateTime.Now;
        // Notify ALL subscribers (including the sidebar badge)
        AlertService.NotifyCountChanged(count);
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;

        await _cts.CancelAsync();
        _cts.Dispose();
    }
}

